mapper.select:
select member_no, member_id, password, name, birth, gender, height, weight, bmi, goal, join_date
from member 
where member_id=#{member_id}

mapper.update:
update member set member_no=#{member_no}, member_id=#{member_id}, password=#{password},
name=#{name}, birth=#{birth}, gender=#{gender}, height=#{height},
weight=#{weight}, bmi=#{bmi}, goal=#{goal}, join_date=#{join_date} where num=#{num}
